// Gimlistream: DJI FPV goggles -> live view on Mac and Windows.
#![cfg_attr(windows, windows_subsystem = "windows")] // no console window behind the app

use minifb::{Key, KeyRepeat, MouseButton, MouseMode, ScaleMode, Window, WindowOptions};
use openh264::{decoder::Decoder, formats::YUVSource};
use std::io::Write;
use std::path::PathBuf;
use std::process::Command;
use std::time::Duration;

const VENDOR_ID: u16 = 0x2ca3;
const PRODUCT_ID: u16 = 0x001f;
const IFACE: u8 = 3;
const MAGIC: &[u8] = b"RMVT";

// App icon as a watermark: 128x128 premultiplied RGBA, generated by assets/make-icon.swift.
const WATERMARK: &[u8; 128 * 128 * 4] = include_bytes!("../assets/watermark.rgba");
const WM_SIZE: usize = 128;
const WM_MARGIN: usize = 16;
const WM_OPACITY: u32 = 77; // of 255, ~30% like the Android app's watermark

/// Blends the watermark into the bottom-right corner of a 0RGB frame. Skips frames too small to hold it.
fn draw_watermark(frame: &mut [u32], w: usize, h: usize) {
    if w < WM_SIZE + WM_MARGIN || h < WM_SIZE + WM_MARGIN {
        return;
    }
    let (x0, y0) = (w - WM_SIZE - WM_MARGIN, h - WM_SIZE - WM_MARGIN);
    for (i, px) in WATERMARK.chunks_exact(4).enumerate() {
        let a = px[3] as u32 * WM_OPACITY / 255;
        if a == 0 {
            continue;
        }
        let dst = &mut frame[(y0 + i / WM_SIZE) * w + x0 + i % WM_SIZE];
        let mix = |shift: u32, s: u8| {
            ((s as u32 * WM_OPACITY + ((*dst >> shift) & 0xff) * (255 - a)) / 255) << shift
        };
        *dst = mix(16, px[0]) | mix(8, px[1]) | mix(0, px[2]);
    }
}

// Start screen, 1280x720 raw RGB, generated by assets/make-menu.swift.
const MENU: &[u8; 1280 * 720 * 3] = include_bytes!("../assets/menu.rgb");
const MENU_W: usize = 1280;
const MENU_H: usize = 720;
/// Live view, Record, Recordings, Diagnostics, Quit: x of each 200x100 button at y 500, as drawn by make-menu.swift.
const MENU_BUTTONS: [usize; 5] = [80, 310, 540, 770, 1000];

/// Which start-screen button is at (x, y) in buffer pixels.
fn menu_button(x: f32, y: f32) -> Option<usize> {
    if !(500.0..600.0).contains(&y) {
        return None;
    }
    MENU_BUTTONS
        .iter()
        .position(|&bx| (bx as f32..bx as f32 + 200.0).contains(&x))
}

/// Red dot in the top-left corner while recording.
fn draw_rec_dot(frame: &mut [u32], w: usize, h: usize) {
    const R: usize = 12;
    const C: usize = 32; // center, from the top-left corner
    if w < 2 * C || h < 2 * C {
        return;
    }
    for y in C - R..=C + R {
        for x in C - R..=C + R {
            if (x.abs_diff(C).pow(2) + y.abs_diff(C).pow(2)) <= R * R {
                frame[y * w + x] = 0x00ff_2020;
            }
        }
    }
}

/// Annex B start code positions (00 00 01), i.e. where each NAL begins.
fn start_codes(buf: &[u8]) -> Vec<usize> {
    buf.windows(3)
        .enumerate()
        .filter(|(_, w)| *w == [0, 0, 1])
        .map(|(i, _)| i)
        .collect()
}

/// Movies (Mac) / Videos (Windows), else the home folder.
fn recordings_dir() -> PathBuf {
    let home = PathBuf::from(
        std::env::var(if cfg!(windows) { "USERPROFILE" } else { "HOME" }).unwrap_or_default(),
    );
    let dir = home.join(if cfg!(windows) { "Videos" } else { "Movies" });
    if dir.is_dir() {
        dir
    } else {
        home
    }
}

/// Opens the recordings folder in Finder / Explorer.
fn open_recordings() {
    let dir = recordings_dir();
    #[cfg(windows)]
    win::open(&dir.to_string_lossy());
    #[cfg(not(windows))]
    let _ = Command::new("open").arg(dir).spawn();
}

/// Next free "Gimlistream N.h264" in recordings_dir().
fn recording_path() -> PathBuf {
    let dir = recordings_dir();
    (1..)
        .map(|i| dir.join(format!("Gimlistream {i}.h264")))
        .find(|p| !p.exists())
        .unwrap()
}

/// Index of the last Annex B start code (00 00 01), i.e. where the unfinished NAL begins.
fn last_start_code(buf: &[u8]) -> Option<usize> {
    buf.windows(3).rposition(|w| w == [0, 0, 1])
}

/// Same limit as NalSplitter.MAX_BUFFER on Android.
const MAX_STREAM_BUF: usize = 8 << 20;

/// Drops `buf` if it grew past MAX_STREAM_BUF without ever yielding a start code.
fn cap_stream(buf: &mut Vec<u8>) {
    if buf.len() > MAX_STREAM_BUF {
        buf.clear();
    }
}

/// Remembers the most recent SPS (type 7) and PPS (type 8) NALs in `buf`.
fn keep_sps_pps(buf: &[u8], sps: &mut Vec<u8>, pps: &mut Vec<u8>) {
    let starts = start_codes(buf);
    for (i, &s) in starts.iter().enumerate() {
        let nal = &buf[s..*starts.get(i + 1).unwrap_or(&buf.len())];
        match nal.get(3).map(|t| t & 0x1f) {
            Some(7) => *sps = nal.to_vec(),
            Some(8) => *pps = nal.to_vec(),
            _ => {}
        }
    }
}

type Res<T> = Result<T, Box<dyn std::error::Error>>;

fn main() -> Res<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.get(1).is_some_and(|a| a == "--diagnostics") {
        print!(
            "{}",
            diagnostics(args.get(2).map_or("run from terminal", |s| s.as_str()))
        );
        return Ok(());
    }
    // Window first: when launched from Finder there's no terminal, so the title is the status line.
    let mut window = Window::new(
        "Gimlistream",
        1280,
        720,
        WindowOptions {
            resize: true,
            scale_mode: ScaleMode::AspectRatioStretch, // letterbox instead of distorting on resize
            ..Default::default()
        },
    )?;
    window.set_target_fps(0); // pace on USB reads, not the display
    let mut app = App {
        window,
        status: String::new(),
        driver_prompted: false,
        recording: false,
        leave: false,
    };

    while let Some(record) = app.menu() {
        app.recording = record;
        app.leave = false;
        app.live();
    }
    Ok(())
}

impl App {
    /// Start screen until a choice is made. Some(record?) starts the live view, None quits.
    fn menu(&mut self) -> Option<bool> {
        self.window.set_title("Gimlistream");
        let img: Vec<u32> = MENU
            .chunks_exact(3)
            .map(|p| u32::from_be_bytes([0, p[0], p[1], p[2]]))
            .collect();
        let mut was_down = true; // ignore a click still held from the previous screen
        while self.window.is_open() {
            let down = self.window.get_mouse_down(MouseButton::Left);
            let click = (down && !was_down).then(|| self.menu_click()).flatten();
            was_down = down;
            let key = |k| self.window.is_key_pressed(k, KeyRepeat::No);
            let choice = if key(Key::Enter) || key(Key::Space) || key(Key::L) {
                Some(0)
            } else if key(Key::R) {
                Some(1)
            } else if key(Key::O) {
                Some(2)
            } else if key(Key::D) {
                Some(3)
            } else if key(Key::Escape) || key(Key::Q) {
                Some(4)
            } else {
                click
            };
            match choice {
                Some(0) => return Some(false),
                Some(1) => return Some(true),
                Some(2) => open_recordings(),
                Some(3) => self.diagnose(),
                Some(_) => return None,
                None => {}
            }
            self.window.update_with_buffer(&img, MENU_W, MENU_H).ok()?;
            std::thread::sleep(Duration::from_millis(16));
        }
        None
    }

    /// Mouse position mapped from window to menu pixels (the window letterboxes the image when resized).
    fn menu_click(&self) -> Option<usize> {
        let (x, y) = self.window.get_mouse_pos(MouseMode::Discard)?;
        let (ww, wh) = self.window.get_size();
        let scale = (ww as f32 / MENU_W as f32).min(wh as f32 / MENU_H as f32);
        let ox = (ww as f32 - MENU_W as f32 * scale) / 2.0;
        let oy = (wh as f32 - MENU_H as f32 * scale) / 2.0;
        menu_button((x - ox) / scale, (y - oy) / scale)
    }

    fn watching(&self) -> bool {
        self.window.is_open() && !self.leave
    }

    /// Live view: find the goggles and stream, retrying, until Esc goes back to the menu.
    fn live(&mut self) {
        while self.watching() {
            let dev = match find_goggles() {
                Ok(Some(d)) => d,
                Ok(None) => {
                    self.set_status(
                        "waiting for goggles (use a USB-C to USB-A adapter, not a C-to-C cable)",
                    );
                    self.idle(Duration::from_secs(1));
                    continue;
                }
                Err(e) => {
                    self.set_status(&format!("couldn't list USB devices: {e}"));
                    self.idle(Duration::from_secs(1));
                    continue;
                }
            };
            let handle = match open_goggles(&dev) {
                Ok(h) => h,
                Err(e) => {
                    self.set_status(&format!("found goggles but can't open them: {e}"));
                    #[cfg(windows)]
                    if !std::mem::replace(&mut self.driver_prompted, true) {
                        offer_driver_install();
                    }
                    self.idle(Duration::from_secs(1));
                    continue;
                }
            };
            self.set_status("connected");
            if let Err(e) = stream(&handle, self) {
                self.set_status(&format!("stream error: {e}, retrying..."));
                self.idle(Duration::from_secs(1));
            }
            let _ = handle.release_interface(IFACE);
        }
    }
}

struct App {
    window: Window,
    status: String,
    #[cfg_attr(not(windows), allow(dead_code))]
    driver_prompted: bool, // Windows: show the Zadig instructions once per run, not every retry
    recording: bool, // wanted by the user; stream() opens/closes the file to match
    leave: bool,     // Esc pressed in the live view: back to the menu
}

impl App {
    fn set_status(&mut self, status: &str) {
        self.status = status.to_string();
        let rec = if self.recording { " - RECORDING" } else { "" };
        self.window.set_title(&format!(
            "Gimlistream - {status}{rec} - R record, D diagnostics, Esc menu"
        ));
    }

    fn idle(&mut self, d: Duration) {
        for _ in 0..d.as_millis() / 50 {
            if !self.watching() {
                return;
            }
            self.window.update();
            self.poll_ui();
            std::thread::sleep(Duration::from_millis(50));
        }
    }

    /// Call once per loop iteration in the live view.
    fn poll_ui(&mut self) {
        if self.window.is_key_pressed(Key::D, KeyRepeat::No) {
            self.diagnose();
        }
        if self.window.is_key_pressed(Key::R, KeyRepeat::No) {
            self.recording = !self.recording;
            self.set_status(&self.status.clone());
        }
        if self.window.is_key_pressed(Key::Escape, KeyRepeat::No) {
            self.leave = true;
        }
    }

    fn diagnose(&self) {
        let report = std::env::current_exe()
            .and_then(|exe| {
                Command::new(exe)
                    .args(["--diagnostics", &self.status])
                    .output()
            })
            .map(|o| String::from_utf8_lossy(&o.stdout).into_owned())
            .unwrap_or_else(|e| format!("couldn't run diagnostics: {e}"));
        show_report(&report);
    }
}

/// Enumerate USB devices and return the goggles, unopened. Errors here are enumeration
/// failures; opening is left to the caller so the two can be reported separately.
fn find_goggles() -> Res<Option<rusb::Device<rusb::GlobalContext>>> {
    for dev in rusb::devices()?.iter() {
        let d = dev.device_descriptor()?;
        if d.vendor_id() == VENDOR_ID && d.product_id() == PRODUCT_ID {
            return Ok(Some(dev));
        }
    }
    Ok(None)
}

fn open_goggles(
    dev: &rusb::Device<rusb::GlobalContext>,
) -> Res<rusb::DeviceHandle<rusb::GlobalContext>> {
    let h = dev.open()?;
    let _ = h.set_auto_detach_kernel_driver(true);
    h.claim_interface(IFACE)?;
    Ok(h)
}

static LOG: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());

extern "system" fn log_cb(
    _: *mut rusb::ffi::libusb_context,
    _: std::ffi::c_int,
    msg: *mut std::ffi::c_void,
) {
    let msg = unsafe { std::ffi::CStr::from_ptr(msg as *const std::ffi::c_char) };
    LOG.lock()
        .unwrap()
        .push(msg.to_string_lossy().trim_end().to_string());
}

/// Plain-text report: what we're looking for, what went wrong, what libusb sees and why,
/// and (macOS) what the OS itself sees via ioreg, so the two can be compared.
fn diagnostics(status: &str) -> String {
    let v = rusb::version();
    let mut out = format!(
        "Looking for: {VENDOR_ID:04x}:{PRODUCT_ID:04x} (DJI FPV Goggles V1/V2)\nStatus: {status}\nlibusb {}.{}.{}\n\nUSB devices seen by libusb:\n",
        v.major(), v.minor(), v.micro()
    );

    // libusb on macOS silently drops devices it can't open and only says why in its debug log.
    // Log level must be set before libusb_init (the scan happens there), hence the env var.
    unsafe {
        rusb::ffi::libusb_set_log_cb(
            std::ptr::null_mut(),
            Some(log_cb),
            rusb::constants::LIBUSB_LOG_CB_GLOBAL,
        );
    }
    std::env::set_var("LIBUSB_DEBUG", "4");
    let list = rusb::devices();
    match list {
        Err(e) => out += &format!("  (can't list devices: {e})\n"),
        Ok(list) if list.is_empty() => out += "  none\n",
        Ok(list) => {
            for dev in list.iter() {
                let Ok(d) = dev.device_descriptor() else {
                    continue;
                };
                let name = dev
                    .open()
                    .ok()
                    .and_then(|h| h.read_product_string_ascii(&d).ok())
                    .unwrap_or_else(|| "?".into());
                let mark = if d.vendor_id() == VENDOR_ID {
                    "  <-- DJI"
                } else {
                    ""
                };
                out += &format!(
                    "  {:04x}:{:04x}  bus {} addr {}  {name}{mark}\n",
                    d.vendor_id(),
                    d.product_id(),
                    dev.bus_number(),
                    dev.address()
                );
            }
        }
    }

    #[cfg(windows)]
    {
        out += "\nWindows: the goggles' interface 3 needs the WinUSB driver, installed once with Zadig.\n";
        out += "  If the DJI line above is there but the status says it can't open them, run Zadig (see README.txt).\n";
    }
    #[cfg(target_os = "macos")]
    {
        let os = std::process::Command::new("sw_vers")
            .arg("-productVersion")
            .output()
            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
            .unwrap_or_default();
        out += &format!("\nmacOS {os}\nUSB devices seen by macOS (ioreg, by class, not via the legacy IOUSB plane):\n");
        match std::process::Command::new("ioreg")
            .args(["-r", "-c", "IOUSBHostDevice", "-l", "-w0"])
            .output()
        {
            Ok(o) => {
                let mut any = false;
                for line in String::from_utf8_lossy(&o.stdout).lines() {
                    let l = line.trim_start_matches([' ', '|']);
                    let keep = l.starts_with("+-o ")
                        || ["\"idVendor\"", "\"idProduct\"", "\"USB Product Name\""]
                            .iter()
                            .any(|k| l.starts_with(k));
                    if keep {
                        out += &format!("  {l}\n");
                        any |= l.starts_with("\"idVendor\"");
                    }
                }
                if !any {
                    out += "  none - goggles aren't detected over USB-C to USB-C: use a USB-C to USB-A adapter\n  plus an A-to-C cable. Also check goggles are powered on and\n  System Settings > Privacy & Security > Allow accessories to connect\n";
                }
            }
            Err(e) => out += &format!("  (ioreg failed: {e})\n"),
        }
    }

    let log = LOG.lock().unwrap();
    out += &format!("\nlibusb debug log ({} lines):\n", log.len());
    for l in log.iter() {
        out += &format!("  {l}\n");
    }
    out
}

/// Windows: save the report to the Desktop and open it in Notepad.
#[cfg(windows)]
fn show_report(text: &str) {
    let desktop =
        std::path::Path::new(&std::env::var("USERPROFILE").unwrap_or_default()).join("Desktop");
    let dir = if desktop.is_dir() {
        desktop
    } else {
        std::env::temp_dir()
    };
    let path = dir.join("Gimlistream-diagnostics.txt");
    match std::fs::write(&path, text) {
        Ok(()) => win::open(&path.to_string_lossy()),
        Err(e) => {
            win::message(
                "Gimlistream diagnostics",
                &format!("Couldn't save report: {e}\n\n{text}"),
                false,
            );
        }
    }
}

/// Windows binds no usable driver to the goggles' video interface; libusb needs WinUSB there (one-time, via Zadig).
#[cfg(windows)]
fn offer_driver_install() {
    let steps = "1. In Zadig: Options > List All Devices\n\
                 2. Select the entry whose USB ID is 2CA3 001F 03 (interface 3 of the goggles)\n\
                 3. Driver: WinUSB, then click Install Driver (or Replace Driver)\n\
                 4. Unplug and replug the goggles";
    let title = "Gimlistream - one-time USB driver setup";
    let zadig = std::env::current_exe()
        .ok()
        .and_then(|p| Some(p.parent()?.join("zadig.exe")))
        .filter(|p| p.exists());
    match zadig {
        Some(z) => {
            if win::message(title, &format!("Windows needs the WinUSB driver to read video from the goggles.\n\n{steps}\n\nOpen Zadig now?"), true) {
                win::open(&z.to_string_lossy()); // ShellExecute, so Zadig's admin (UAC) prompt works
            }
        }
        None => {
            win::message(title, &format!("Windows needs the WinUSB driver to read video from the goggles.\n\nDownload Zadig from https://zadig.akeo.ie, then:\n\n{steps}"), false);
        }
    }
}

#[cfg(windows)]
mod win {
    use std::ffi::c_void;
    use std::os::windows::ffi::OsStrExt;

    #[link(name = "user32")]
    extern "system" {
        fn MessageBoxW(hwnd: *mut c_void, text: *const u16, caption: *const u16, kind: u32) -> i32;
    }
    #[link(name = "shell32")]
    extern "system" {
        fn ShellExecuteW(
            hwnd: *mut c_void,
            op: *const u16,
            file: *const u16,
            params: *const u16,
            dir: *const u16,
            show: i32,
        ) -> *mut c_void;
    }

    fn wide(s: &str) -> Vec<u16> {
        std::ffi::OsStr::new(s)
            .encode_wide()
            .chain(Some(0))
            .collect()
    }

    /// Blocking message box. With `yes_no`, returns whether Yes was clicked.
    pub fn message(title: &str, text: &str, yes_no: bool) -> bool {
        const MB_YESNO: u32 = 0x4;
        const MB_ICONINFORMATION: u32 = 0x40;
        const IDYES: i32 = 6;
        let kind = MB_ICONINFORMATION | if yes_no { MB_YESNO } else { 0 };
        unsafe {
            MessageBoxW(
                std::ptr::null_mut(),
                wide(text).as_ptr(),
                wide(title).as_ptr(),
                kind,
            ) == IDYES
        }
    }

    /// Opens a file or program the way Explorer would (handles UAC elevation for Zadig).
    pub fn open(path: &str) {
        unsafe {
            ShellExecuteW(
                std::ptr::null_mut(),
                wide("open").as_ptr(),
                wide(path).as_ptr(),
                std::ptr::null(),
                std::ptr::null(),
                1,
            );
        }
    }
}

/// Native dialog via osascript (no GUI deps), non-blocking. Saves the full report to the Desktop, shows the top, Copy puts all of it on the clipboard.
#[cfg(not(windows))]
fn show_report(text: &str) {
    eprintln!("{text}");
    let path = std::env::var("HOME").unwrap_or_default() + "/Desktop/Gimlistream-diagnostics.txt";
    let saved = std::fs::write(&path, text).is_ok();
    let mut short: String = text.lines().take(40).collect::<Vec<_>>().join("\n");
    if saved {
        short += &format!("\n\nFull report saved to {path}");
    }

    let _ = Command::new("osascript")
        .args(["-e", "on run argv",
               "-e", "set t to item 1 of argv",
               "-e", "set full to item 2 of argv",
               "-e", "set r to display dialog t with title \"Gimlistream diagnostics\" buttons {\"Copy\", \"OK\"} default button \"OK\"",
               "-e", "if button returned of r is \"Copy\" then set the clipboard to full",
               "-e", "end run", &short, text])
        .spawn();
}

/// Streams video into the window until it closes or the device errors out (e.g. unplugged).
fn stream(handle: &rusb::DeviceHandle<rusb::GlobalContext>, app: &mut App) -> Res<()> {
    // Android code uses endpoint 0 as OUT and endpoint 1 as IN on interface 3.
    let cfg = handle.device().active_config_descriptor()?;
    let alt = cfg
        .interfaces()
        .find(|i| i.number() == IFACE)
        .ok_or("no interface 3")?
        .descriptors()
        .next()
        .ok_or("no alt setting")?;
    let eps: Vec<_> = alt.endpoint_descriptors().collect();
    let ep_out = eps
        .iter()
        .find(|e| e.direction() == rusb::Direction::Out)
        .ok_or("no OUT ep")?
        .address();
    let ep_in = eps
        .iter()
        .find(|e| e.direction() == rusb::Direction::In)
        .ok_or("no IN ep")?
        .address();

    handle.write_bulk(ep_out, MAGIC, Duration::from_secs(2))?;

    let mut decoder = Decoder::new()?;
    let (mut rgb, mut frame) = (Vec::new(), Vec::new());
    let mut chunk = vec![0u8; 131072];
    let mut stream: Vec<u8> = Vec::new();
    // Raw H.264 recording. SPS/PPS are kept so a file started mid-stream is still playable.
    let mut rec: Option<(std::io::BufWriter<std::fs::File>, PathBuf)> = None;
    let (mut sps, mut pps) = (Vec::new(), Vec::new());

    app.set_status("streaming");
    let mut err = None;
    while app.watching() {
        app.poll_ui();
        let read = handle.read_bulk(ep_in, &mut chunk, Duration::from_millis(100));
        match read_action(&read) {
            ReadAction::Data(n) => stream.extend_from_slice(&chunk[..n]),
            ReadAction::Poke => {
                // Goggles stop streaming until poked again.
                let _ = handle.write_bulk(ep_out, MAGIC, Duration::from_secs(2));
                app.window.update();
                continue;
            }
            ReadAction::Retry => {
                app.window.update();
                continue;
            }
            // Don't `return` here: the recording below must still be flushed and reported.
            ReadAction::Fail => {
                err = read.err();
                break;
            }
        }

        let Some(cut) = last_start_code(&stream).filter(|&c| c > 0) else {
            cap_stream(&mut stream);
            continue;
        };
        let complete: Vec<u8> = stream.drain(..cut).collect();

        keep_sps_pps(&complete, &mut sps, &mut pps);
        if app.recording != rec.is_some() {
            match rec.take() {
                Some((mut f, path)) => {
                    let _ = f.flush();
                    app.set_status(&format!("saved {}", path.display()));
                }
                None => {
                    let path = recording_path();
                    match std::fs::File::create(&path) {
                        Ok(f) => {
                            let mut f = std::io::BufWriter::new(f);
                            let _ = f.write_all(&[sps.as_slice(), &pps].concat());
                            app.set_status(&format!("recording to {}", path.display()));
                            rec = Some((f, path));
                        }
                        Err(e) => {
                            app.recording = false;
                            app.set_status(&format!("can't record to {}: {e}", path.display()));
                        }
                    }
                }
            }
        }
        if let Some((f, path)) = &mut rec {
            if let Err(e) = f.write_all(&complete) {
                let msg = format!("recording to {} stopped: {e}", path.display());
                rec = None;
                app.recording = false;
                app.set_status(&msg);
            }
        }
        match decoder.decode(&complete) {
            Ok(Some(yuv)) => {
                let (w, h) = yuv.dimensions();
                rgb.resize(w * h * 3, 0);
                yuv.write_rgb8(&mut rgb);
                frame.clear();
                frame.extend(
                    rgb.chunks_exact(3)
                        .map(|p| u32::from_be_bytes([0, p[0], p[1], p[2]])),
                );
                draw_watermark(&mut frame, w, h);
                if rec.is_some() {
                    draw_rec_dot(&mut frame, w, h);
                }
                app.window.update_with_buffer(&frame, w, h)?;
            }
            Ok(None) => {}
            Err(e) => eprintln!("decode: {e}"), // corrupt NAL over the air link; keep going
        }
    }
    if let Some((mut f, path)) = rec {
        let _ = f.flush();
        app.set_status(&format!("saved {}", path.display()));
    }
    err.map_or(Ok(()), |e| Err(e.into()))
}

enum ReadAction {
    Data(usize),
    Poke,
    Retry,
    Fail,
}

/// Timeout re-pokes the goggles; an empty read or EINTR just retries (no poke, so no write spin); anything else ends the stream.
fn read_action(r: &Result<usize, rusb::Error>) -> ReadAction {
    match r {
        Ok(0) | Err(rusb::Error::Interrupted) => ReadAction::Retry,
        Ok(n) => ReadAction::Data(*n),
        Err(rusb::Error::Timeout) => ReadAction::Poke,
        Err(_) => ReadAction::Fail,
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn read_actions() {
        use super::{read_action as a, ReadAction as R};
        assert!(matches!(a(&Ok(5)), R::Data(5)));
        assert!(matches!(a(&Ok(0)), R::Retry));
        assert!(matches!(a(&Err(rusb::Error::Interrupted)), R::Retry));
        assert!(matches!(a(&Err(rusb::Error::Timeout)), R::Poke));
        assert!(matches!(a(&Err(rusb::Error::NoDevice)), R::Fail));
    }

    #[test]
    fn caps_stream_without_start_code() {
        let mut buf = vec![7u8; super::MAX_STREAM_BUF];
        super::cap_stream(&mut buf);
        assert_eq!(buf.len(), super::MAX_STREAM_BUF);
        buf.push(7);
        super::cap_stream(&mut buf);
        assert!(buf.is_empty());
    }

    #[test]
    fn capped_stream_stays_bounded_and_recovers() {
        // Feed start-code-free junk like stream() does: buffer never exceeds cap + one chunk.
        let (mut stream, chunk) = (Vec::new(), vec![7u8; 1 << 20]);
        for _ in 0..20 {
            stream.extend_from_slice(&chunk);
            if super::last_start_code(&stream).filter(|&c| c > 0).is_none() {
                super::cap_stream(&mut stream);
            }
            assert!(stream.len() <= super::MAX_STREAM_BUF);
        }
        // After trimming, new NALs are still found and the kept tail starts at a start code.
        stream.extend_from_slice(&[0, 0, 1, 0x67, 1, 0, 0, 1, 0x68]);
        let cut = super::last_start_code(&stream).unwrap();
        assert_eq!(cut, stream.len() - 4);
        assert_eq!(&stream[cut..], &[0, 0, 1, 0x68]);
    }

    #[test]
    fn splits_at_last_start_code() {
        let buf = [0, 0, 0, 1, 0x67, 9, 0, 0, 1, 0x68, 7];
        assert_eq!(super::last_start_code(&buf), Some(6));
        assert_eq!(super::last_start_code(&[1, 2, 3]), None);
    }

    #[test]
    fn split_handles_chunk_boundaries() {
        // Same cut logic as stream(): only drain up to the last start code.
        let data = [0, 0, 1, 0x67, 1, 2, 0, 0, 1, 0x68, 3, 0, 0, 1, 0x65, 4];
        for split in 0..=data.len() {
            let (mut stream, mut out) = (Vec::new(), Vec::new());
            for chunk in [&data[..split], &data[split..]] {
                stream.extend_from_slice(chunk);
                if let Some(cut) = super::last_start_code(&stream).filter(|&c| c > 0) {
                    out.extend(stream.drain(..cut));
                    // The piece just drained ends right before a start code.
                    assert!(
                        stream.starts_with(&[0, 0, 1]),
                        "cut at {cut}, split {split}"
                    );
                }
                // Remainder starts at a start code, or is empty / a partial one.
                assert!(
                    stream.starts_with(&[0, 0, 1]) || [0, 0, 1].starts_with(&stream),
                    "remainder {stream:?}, split {split}"
                );
            }
            out.extend(&stream);
            assert_eq!(out, data, "split at {split}");
        }
    }

    #[test]
    fn keeps_latest_sps_pps() {
        let (mut sps, mut pps) = (Vec::new(), Vec::new());
        super::keep_sps_pps(
            &[0, 0, 1, 0x67, 1, 0, 0, 1, 0x68, 2, 0, 0, 1, 0x65, 9],
            &mut sps,
            &mut pps,
        );
        assert_eq!(
            (&sps[..], &pps[..]),
            (&[0, 0, 1, 0x67, 1][..], &[0, 0, 1, 0x68, 2][..])
        );
        super::keep_sps_pps(&[0, 0, 1, 0x67, 5, 0, 0, 1, 0x41, 9], &mut sps, &mut pps);
        assert_eq!(sps, [0, 0, 1, 0x67, 5], "newer SPS replaces old");
        assert_eq!(pps, [0, 0, 1, 0x68, 2], "PPS kept when absent");
    }

    #[test]
    fn finds_start_codes_and_menu_buttons() {
        assert_eq!(
            super::start_codes(&[0, 0, 0, 1, 0x67, 9, 0, 0, 1, 0x68]),
            vec![1, 6]
        );
        assert_eq!(super::menu_button(220.0, 550.0), Some(0));
        assert_eq!(super::menu_button(1100.0, 599.0), Some(4));
        assert_eq!(
            super::menu_button(295.0, 550.0),
            None,
            "gap between buttons"
        );
        assert_eq!(super::menu_button(220.0, 450.0), None, "above the buttons");
    }

    #[test]
    fn menu_button_edges() {
        assert_eq!(super::menu_button(80.0, 500.0), Some(0), "top-left inclusive");
        assert_eq!(super::menu_button(280.0, 550.0), None, "right edge exclusive");
        assert_eq!(super::menu_button(1000.0, 600.0), None, "bottom edge exclusive");
        assert_eq!(super::menu_button(1200.0, 550.0), None, "right of last button");
    }

    #[test]
    fn rec_dot_is_drawn_in_corner_only() {
        let (w, h) = (100, 100);
        let mut frame = vec![0u32; w * h];
        super::draw_rec_dot(&mut frame, w, h);
        assert_eq!(frame[32 * w + 32], 0x00ff_2020, "center is red");
        assert_eq!(frame[32 * w + 32 + 13], 0, "outside radius untouched");
        assert!(frame.iter().filter(|&&p| p != 0).count() > 400);
        super::draw_rec_dot(&mut [0; 100], 10, 10); // too small: no panic
    }

    #[test]
    fn watermark_blends_into_bottom_right() {
        use super::{draw_watermark, WM_MARGIN, WM_SIZE};
        let (w, h) = (1280, 720);
        let mut frame = vec![0x00ff_ffffu32; w * h];
        draw_watermark(&mut frame, w, h);
        let at = |x: usize, y: usize| frame[y * w + x];
        let (x0, y0) = (w - WM_SIZE - WM_MARGIN, h - WM_SIZE - WM_MARGIN);
        assert_eq!(at(x0, y0), 0x00ff_ffff, "rounded corner is transparent");
        let c = at(x0 + WM_SIZE / 2, y0 + WM_SIZE / 2); // dark cat nose over white
        assert!(
            c < 0x00ff_ffff && (c >> 16) & 0xff > 0x99,
            "faint, not opaque: {c:06x}"
        );
        assert_eq!(at(10, 10), 0x00ff_ffff, "rest of frame untouched");
        draw_watermark(&mut [0; 100], 10, 10); // too small: no panic
    }
}
